/bin/zsh -lc "cat > src/orchestration/tools/registry.legacy-path.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#3
it('reports a nested required path from a validator using dataPath', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object'}},
    async () => 'sunny'
  );
  const validate = Object.assign(() => false, {
    errors: [{dataPath: '/address', keyword: 'required', params: {missingProperty: 'location'}}],
  });
  const tools = (registry as unknown as {tools: Map<string, {validator: typeof validate}>}).tools;
  tools.get('weather')"'!.validator = validate;
  const response = await registry.execute('"'weather', {address: {}});
  expect(response.result).toContain('/address/location required');
});
EOF
